mapper.select:
SELECT FIN_PRODUCT.FINPROD_MARKET_ID id, FIN_PRODUCT.FINPROD_ABBR text, concat_ws('', FIN_PRODUCT.FINPROD_ID, ',', FIN_PRODUCT.PROFIT_TYPE, ',', FIN_PRODUCT.FINPROD_ABBR, ',', FIN_PRODUCT_ADD.DEAL_MODE) object FROM FIN_PRODUCT LEFT JOIN FIN_PRODUCT_ADD ON FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID INNER JOIN PTL_MANAGE_OBJ ON PTL_MANAGE_OBJ.MANAGE_OBJ_ID = FIN_PRODUCT.FINPROD_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY ON PTL_MANAGE_OBJ.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID where FIN_PRODUCT.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F16,jdbcType=VARCHAR} AND FIN_PRODUCT.PROFIT_TYPE IN (#{PROFIT_TYPE_01,jdbcType=VARCHAR},#{PROFIT_TYPE_03,jdbcType=VARCHAR})
AND (FIN_PRODUCT.FINPROD_MARKET_ID LIKE CONCAT('%',#{search,jdbcType=VARCHAR},'%') or FIN_PRODUCT.FINPROD_ABBR LIKE CONCAT('%',#{search,jdbcType=VARCHAR},'%') )
AND FIN_PRODUCT.FINPROD_MARKET_ID = #{initValue,jdbcType=VARCHAR}
AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userName}
AND FIN_PRODUCT.MDATE >= STR_TO_DATE(#{SESSION_SYS_DATE},'%Y-%m-%d')

SELECT distinct A.FINPROD_ID as finprodId, A.FINPROD_MARKET_ID as finprodMarketId, IFNULL(C.FINPROD_ABBR,A.FINPROD_ABBR) as finprodAbbr, B.BASE_RULE_ID as baseRuleId, B.COEFFICIENT as coefficient, B.RATE*100 as rate, CASE WHEN B.PUBLISH_TYPE = #{yesOrNo_Yes} THEN CONCAT_WS( '',FORMAT(CAST(B.RATE_LOWER*100 AS DECIMAL(12,2)),4), '~',FORMAT(CAST(B.RATE_LIMIT*100 AS DECIMAL(12,2)),4) ) ELSE FORMAT(CAST(B.RATE*100 AS DECIMAL(12,2)),4) end as rates, B.SPREAD_RATE*100 as spreadRate, B.RESET_TYPE as resetType, B.EFF_DATE as effDate, B.RATE_TYPE as rateType, B.INDEX_ID as indexId, B.INDEX_SOURCE as indexSource, lay.PROD_STYLE prodStyle, PMSI.SEND_STATUS sendStatus, PMSI.SEND_REMARK sendRemark, CASE WHEN B.PUBLISH_TYPE = '01' THEN CONCAT_WS('', trim(FORMAT(CAST(B.RATE_LOWER*100 AS DECIMAL(12,2)),4)),'%','~', trim(FORMAT(CAST(B.RATE_LIMIT*100 AS DECIMAL(12,2)),4)),'%' ) ELSE '' end as lowLimitRate, D.INVESTMENT_CYCLE investmentCycle
,B.BASE_RULE_TYPE baseRuleType
FROM FIN_PRODUCT A LEFT JOIN FIN_PRODUCT C ON A.P_FINPROD_ID = C.FINPROD_ID INNER JOIN PTL_MANAGE_OBJ
ON ((A.p_Finprod_Id is null and PTL_MANAGE_OBJ.MANAGE_OBJ_ID = A.FINPROD_ID) or(A.p_Finprod_Id is not null and PTL_MANAGE_OBJ.MANAGE_OBJ_ID = A.P_FINPROD_ID))
INNER JOIN PTL_PORTFOLIO_AUTHORITY ON PTL_MANAGE_OBJ.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userName} INNER JOIN FIN_PRODUCT_ADD D ON A.FINPROD_ID = D.FINPROD_ID LEFT JOIN prd_layer_param lay ON A.FINPROD_ID = lay.FINPROD_ID , FIN_BASE_RULE_INFO B LEFT JOIN INF_FIN_BASE_RULE_INFO PMSI ON B.BASE_RULE_ID =PMSI.BASE_RULE_ID AND B.EFF_DATE = PMSI.EFF_DATE WHERE A.FINPROD_TYPE2 in (#{FINPROD_TYPE_TG_F16,jdbcType=VARCHAR},#{FINPROD_TYPE_TG_F24,jdbcType=VARCHAR},#{FINPROD_TYPE_TG_F26,jdbcType=VARCHAR}) AND A.PROFIT_TYPE IN (#{PROFIT_TYPE_01,jdbcType=VARCHAR},#{PROFIT_TYPE_03,jdbcType=VARCHAR}) AND A.FINPROD_ID = B.FINPROD_ID AND B.BRANCH = 0 AND B.BASE_RULE_TYPE = #{BASE_RULE_TYPE_01,jdbcType=VARCHAR} AND ((D.DEAL_MODE = #{DISPOSE_PATTERN_10,jdbcType=VARCHAR} AND A.P_FINPROD_ID IS NOT NULL ) OR D.DEAL_MODE != #{DISPOSE_PATTERN_10,jdbcType=VARCHAR})
AND A.FINPROD_MARKET_ID IN
#{item}
AND lay.PROD_STYLE IN
#{item}
AND IFNULL(PMSI.SEND_STATUS, '03') = #{sendStatus,jdbcType=VARCHAR}
AND B.EFF_DATE between STR_TO_DATE(#{sDate},'%Y-%m-%d') and STR_TO_DATE(#{eDate},'%Y-%m-%d')
#{key,jdbcType=VARCHAR}
ORDER BY A.FINPROD_ID ASC, B.EFF_DATE DESC

select
COUNT(1)
from
FIN_CASH_INFO A,
FIN_FLOAT_COUNTING_RULE B
where
A.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
AND	A.CASH_ID =	B.CASH_ID
AND	A.CASH_TYPE_2 = #{CASH_TYPE_2_C04,jdbcType=VARCHAR}
AND	B.EFF_DATE >	STR_TO_DATE(#{effDate},'%Y-%m-%d')
UNION ALL
select
COUNT(1)
from FIN_CASH_INFO C,	FIN_CASH_PAY_RULE D
where
C.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
AND	C.CASH_ID =	D.CASH_ID
AND	C.CASH_TYPE_2 = #{CASH_TYPE_2_C04,jdbcType=VARCHAR}
AND	D.EFF_DATE > STR_TO_DATE(#{effDate},'%Y-%m-%d')

UNION ALL
select count(1) from BOK_POSITION_PRDFEE
where BOK_POSITION_PRDFEE.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
and BOK_POSITION_PRDFEE.FEE_TYPE = #{CASH_TYPE_2_C04,jdbcType=VARCHAR}
and BOK_POSITION_PRDFEE.CDATE >  STR_TO_DATE(#{effDate},'%Y-%m-%d')
UNION ALL
SELECT COUNT(1) FROM TRD_PRODUCT_DEAL E,TRD_TRADE_FEE_DETAIL F
WHERE E.TRADE_ID = F.TRADE_ID
AND E.IS_CANCEL = #{YES_OR_NO_N,jdbcType=VARCHAR}
AND E.TRADE_STATUS =  #{TRADE_STATUS_01,jdbcType=VARCHAR}
AND E.SETTLE_DATE> STR_TO_DATE(#{effDate},'%Y-%m-%d')
AND F.FEE_TYPE = #{CASH_TYPE_2_C04,jdbcType=VARCHAR}
AND E.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
